## 2. Armazenamento local (histórico + progresso por arquivo)

```csharp
// src/Data/IDownloadStore.cs
using System.IO;
using System.Text.Json;
using Microsoft.Extensions.Logging;

namespace MyApp.Data;

/// <summary>
/// Controla a pasta "Patch/", o manifest.json global e o progresso por arquivo
/// (gravado em arquivos .json ao lado de cada binário, para viabilizar a retomada).
/// </summary>
public interface IDownloadStore
{
    string Root { get; }

    void EnsurePatchDirectory();

    Manifest CurrentManifest { get; }
    FileRecord GetRecord(string fileName);
    void UpdateRecord(string fileName, FileRecord record);
    void DeleteRecord(string fileName);

    long GetCurrentOffset(string fileName);
    void SaveCurrentOffset(string fileName, long bytes);
}

public record Manifest(IReadOnlyDictionary<string, FileRecord> Files, DateTimeOffset LastScanUtc);
public record FileRecord(string FileName, int Version, long SizeBytes, string Integrity,
    FileStatus Status, DateTimeOffset CreatedAt, DateTimeOffset? CompletedAt = null);
public enum FileStatus { Pending, InProgress, Completed, Failed, Skipped }

// ----------------------------------------------------------
// Implementação em disco (.NET 8+ suporta campos privados nas classes sealadas)
// ----------------------------------------------------------
public sealed class FileSystemDownloadStore : IDownloadStore
{
    private readonly string _root;
    private AutoResetMutex _lock = new AutoResetMutex(".PatchStore.Lock");

    public FileSystemDownloadStore(string root)
    {
        _root = Path.EnforceTrailingSlash(root);
    }

    public string Root => _root;

    public void EnsurePatchDirectory()
    {
        Directory.CreateDirectory(Path.Combine(_root, "Patch"));
    }

    private void Guard(string label)
    {
        if (!_lock.AcquireTimeout(500))
            throw new InvalidOperationException($"Conflito de arquivos em {label}. Verifique execuções simultâneas.");
    }

    public Manifest CurrentManifest
    {
        get
        {
            Guard("manifest");
            try
            {
                var p = Path.Combine(_root, "manifest.patch.json");
                if (!File.Exists(p))
                    return new Manifest(new Dictionary<string, FileRecord>(), DateTimeOffset.MinValue);
                var lines = File.ReadAllLines(p);
                var opts = new JsonSerializerOptions { PropertyNameCaseInsensitive = true };
                return JsonSerializer.Deserialize<Manifest>(lines, opts)
                    ?? new Manifest(new Dictionary<string, FileRecord>(), DateTimeOffset.MinValue);
            }
            finally { _lock.Release(); }
        }
    }

    public FileRecord GetRecord(string fileName)
    {
        Guard($"record-{fileName}");
        try
        {
            var p = Path.Combine(_root, $"record_{fileName}.json");
            if (!File.Exists(p)) return default;
            var t = File.ReadAllText(p);
            return JsonSerializer.Deserialize<FileRecord>(t, new JsonSerializerOptions { PropertyNameCaseInsensitive = true }) ?? default;
        }
        finally { _lock.Release(); }
    }

    public void UpdateRecord(string fileName, FileRecord record)
    {
        Guard($"record-{fileName}-write");
        try { JsonSerializer.Serialize(File.OpenWrite(Path.Combine(_root, $"record_{fileName}.json")), record, new JsonSerializerOptions { PropertyNameCaseInsensitive = true }); }
        catch { /* silencioso */ }
        finally { _lock.Release(); }
    }

    public void DeleteRecord(string fileName)
    {
        try { if (File.Exists(Path.Combine(_root, $"record_{fileName}.json"))) File.Delete(Path.Combine(_root, $"record_{fileName}.json")); } catch { }
    }

    public long GetCurrentOffset(string fileName)
    {
        var p = Path.Combine(_root, $"progress_{fileName}.json");
        if (!File.Exists(p)) return 0;
        var o = JsonSerializer.Deserialize<ProgressPayload>(File.ReadAllText(p), new JsonSerializerOptions { PropertyNameCaseInsensitive = true });
        return o?.LastWritten ?? 0;
    }

    public void SaveCurrentOffset(string fileName, long bytes)
    {
        var p = Path.Combine(_root, $"progress_{fileName}.json");
        var payload = new ProgressPayload { LastWritten = bytes, Updated = DateTimeOffset.UtcNow.ToString("O") };
        JsonSerializer.Serialize(File.OpenWrite(p), payload, new JsonSerializerOptions { PropertyNameCaseInsensitive = true });
    }

    private sealed class ProgressPayload { public long LastWritten { get; set; } public string? Updated { get; set; } }
}
```

**Por que dois mecanismos?** `manifest.patch.json` guarda o *estado global* (o que já está bom, o que falta, o que foi pulado). O arquivo `progress_*.json` guarda o *posico* do último byte escrito de cada arquivo em andamento — é isso que permite **retomar de onde parou** após queda.

