### 5.2 `DownloadPanel._CodeBehind.cs` (motor de sincronização + estado)

```csharp
// src/DownloadPanel._CodeBehind.cs
using System.Net.Http;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;

namespace MyApp.Download;

public enum DownloadStatus
{
    Idle, Connecting, Authenticating, Preparing,
    Downloading, Verifying, Paused, Skipping, Done, Error
}

/// <remarks>
/// Herda de ObservableObject para tornar o state reativo ao Blazor.
/// Como não usamos CommunityToolkit.MUI, basta este import — se o editor reclamar,
/// adicione "using CommunityToolkit.Mui.UI.Core.Interactivity.Primitives;"
/// </remarks>
public partial class DownloadPanel : Component<BaseState, DownloadPanelState>
{
    private readonly HttpClient _http;
    private readonly IDownloadStore _store;
    private readonly IOptionsMonitor<PatchSettingsSnapshot> _opts;
    private readonly ILogger<DownloadPanel> _log;

    // --- callbacks (motor de sincronização ➜ componente) ---
    private PatchCallbacks _cb = new();

    // --- state interno do motor ---
    private readonly PatchOrchestrator _orch = null!;
    private volatile bool _paused;

    // --- helpers estáticos usados no Razor ---
    public static string BytesStr(long bytes) =>
        bytes switch
        {
            0 => "0 B",
            < 1024  => $"{bytes} B",
            < 1048576 => $"{bytes / 1024} KB",
            < 1073741824 => $"{bytes / 1048576 / 1024,0} MB",
            _ => $"{bytes / 1073741824,0} GB"
        }.ToString();

    public static double PctComplete(long downloaded, long total) =>
        total > 0 ? Math.Round((double)downloaded / total * 100) : 0;

    public static string HumanBytes(long bytes) =>
        bytes switch
        {
            0 => "0 B",
            < 1024 => $"{bytes} B",
            < 1048576 => $"{bytes / 1024,0} KB",
            < 1073741824 => $"{bytes / 1048576 / 1024,0} MB",
            _ => $"{bytes / 1073741824 / 1024,0} GB"
        }.ToString();

    public DownloadPanel(HttpClient factory, IDownloadStore store,
        IOptionsMonitor<PatchSettingsSnapshot> opts, ILogger<DownloadPanel> log)
    {
        _http = factory.CreateClient("PatchDl");
        _store = store;
        _opts = opts;
        _http.BaseAddress = new Uri(_opts.Current.ServerUrl);
    }

    public override void OnInitialized()
    {
        // URL pode ser trocada à quente se precisar
        // (opcional — mantida fixa via opções)

        var cb = new PatchCallbacks();
        _orch = new PatchOrchestrator(_http, _store, cb, _log, _opts);
        _orch.Subscribe(cb);
        _orch.Start();

        State.StatusLine = "Conectando ao servidor...";
        State.Status = DownloadStatus.Idle;
        _queueRefresh(); // atualiza o preview da fila quando não há download
    }

    public override void OnDispose() => _orch?.Stop();

    // ------------------------- Dispositivos de evento -------------------------

    private void TryClose() => State.IsActive = false;

    /// <summary>Conecte/Reconecte (liga o ping de saúde do motor).</summary>
    public async Task TryReconnect()
    {
        State.Status = DownloadStatus.Connecting;
        State.StatusLine = "Reconectando ao servidor...";
        try
        {
            var ok = await _http.GetAsync("/api/status", CancellationToken.None);
            if (ok.IsSuccessStatusCode)
            {
                _orch._lastPingOk = 1;
                _orch.CancelPauseIfActive();
                _cb.InvokeConnect(new ConnectResult(true, "Conexão restabelecida — refazendo verificação de arquivos."));
                if (_orch._scanning) return; // já está escaneando
                _orch.BeginScan(CancellationToken.None);
            }
            else
            {
                _orch._lastPingOk = 0;
                _cb.InvokeConnect(new ConnectResult(false, "Reconexão momentânea falhou — aguardando..."));
            }
        }
        catch (HttpRequestException)
        {
            _cb.InvokeConnect(new ConnectResult(false, "Sem conexão no momento."));
        }
    }

    /// <summary>Aborta varredura em curso e reencaminha para nova conexão/varredura.</summary>
    public void AttemptReconnect()
    {
        State.Status = DownloadStatus.Connecting;
        State.StatusLine = "Reconectando ao servidor...";
        _orch.TryReconnect();
    }

    // ------------------------- Dispositivos do usuário -------------------------

    public void HandleSkip()
    {
        if (!State.IsActive || State.IsDownloading || State.IsPaused) return;
        var item = _workFirst(State.Active.FileName);
        var entry = item?.Entry ?? new UpdateEntry(0, State.Active.FileName, "");
        _cb.InvokeDecision(new PendingDecision(
            DecisionKind.SkipMissing, entry,
            null, $"Arquivo '{entry.FileName}' não disponível no servidor — pulando.", 5));
    }

    public void HandleForce()
    {
        if (!State.IsActive || State.IsDownloading || State.IsPaused) return;
        var item = _workFirst(State.Active.FileName);
        if (item is not null)
        {
            _store.DeleteRecord(item.Entry.FileName);
            _cb.InvokeDecision(new PendingDecision(
                DecisionKind.DownloadFresh, item.Entry, null,
                $"Removendo registro de {item.Entry.FileName} e rebaixando do zero.", 0));
        }
        else
        {
            var e = new UpdateEntry(0, State.Active.FileName, "");
            _cb.InvokeDecision(new PendingDecision(
                DecisionKind.SkipMissing, e, null, "Arquivo não localizado; pulando.", 5));
        }
    }

    public void HandleReconnect() => AttemptReconnect();

    // ------------------------- Fluxo de decisão (callback do motor) --------

    private void ApplyConnect(ConnectResult r)
    {
        State.IsConnected = r.Ok;
        State.Status = r.Ok ? DownloadStatus.Idle : DownloadStatus.Connecting;
        State.StatusLine = r.Mensagem ?? (r.Ok
            ? "Servidor conectado. Verificando atualizações..."
            : "Sem conexão — tentará novamente automaticamente...");
        if (!r.Ok) _orch.TryReconnect();
        else BeginScan();
    }

    private void ApplyAuth(AuthResult a)
    {
        State.IsAuthenticated = a.Ok;
        if (a.Ok)
        {
            State.StatusLine = "Autorização no servidor concluída. Verificando pendências...";
            BeginScan();
        }
        else
        {
            State.ErrorText = a.Mensagem ?? "Falha na autenticação.";
            State.ErrorKind = MapErrorKind(a.ErrKind ?? "Unknown");
            State.Status = DownloadStatus.Error;
            AttemptReconnect();
        }
    }

    private void BeginScan()
    {
        State.StatusLine = "Preparando para verificar arquivos pendentes...";
        _orch.BeginScan(CancellationToken.None);
    }

    private void DispatchDecision(PendingDecision pd)
    {
        switch (pd.Kind)
        {
            case DecisionKind.SkipMissing:
                if (pd.SegundosRestantes > 0)
                {
                    State.StatusLine = $"Salto em '{pd.Entry.FileName}' — restam {pd.SegundosRestantes}s...";
                    BeginSkipCountdown(pd.SegundosRestantes);
                }
                else
                {
                    State.History.Add(new SkippedItem(pd.Entry, "Arquivo ausente no servidor — pulado definitivamente.", 0));
                    State.StatusLine = $"Pulou {pd.Entry.FileName}: não estava disponível no servidor.";
                }
                break;

            case DecisionKind.SkipVerified:
                State.History.Add(new SkippedItem(pd.Entry, "Arquivo já existe e o hash foi conferido — íntegro.", 0));
                State.StatusDetail += " • " + pd.Entry.FileName;
                break;

            case DecisionKind.DownloadFresh:
            case DecisionKind.Resume:
                ActivateDownload(pd.Entry, pd.KnownOffset ?? 0, pd.Mensagem ?? null);
                break;

            case DecisionKind.Fail:
                State.History.Add(new SkippedItem(pd.Entry, $"Falha em {pd.Entry.FileName}: {pd.Mensagem ?? "erro desconhecido"}", 0));
                State.ErrorText = $"Falha: {pd.Mensagem ?? "motivo não informado"}";
                State.Status = DownloadStatus.Error;
                State.StatusLine = $"Falha: {pd.Mensagem ?? "detalhe não informado"}";
                _orch.AttemptReconnect();
                break;
        }
    }

    private void ActivateDownload(UpdateEntry entry, long offset, string note)
    {
        if (State.IsDownloading) return; // protege contra chamada dupla (gating atômico no motor)
        if (State.IsPaused)
        {
            // suspensão externa: não inicia novo download até o usuário retomar
            State.Status = DownloadStatus.Paused;
            return;
        }

        State.IsActive = true;
        State.Status = DownloadStatus.Preparing;
        State.StatusLine = "Preparando para iniciar o download...";
        State.Active = new ActiveDownload(entry.FileName, entry.Version, 0, 0,
            DateTimeOffset.UtcNow, note: note);
        _orch.KickDownload(entry.FileName, offset);
    }

    private void ApplyCompleted(CompletedEntry e)
    { /* nada visual imediato — o estado de "Done" já é refletido nas cores */ }

    private void ApplyFail(FailInfo f)
    {
        // já tratado em DispatchDecision (caso Fail) — este ramo serve para falhas externas
        State.ErrorText = f.Explicacao;
        State.Status = DownloadStatus.Error;
        AttemptReconnect();
    }

    private void ApplyCycle(CycleReport r)
    {
        State.CycleLogs.Add(r);
        ComputeSummary(r);
    }

    private void ComputeSummary(CycleReport last)
    {
        var baixados = State.CycleLogs.SelectMany(l => l.Baixados).Distinct().Count();
        var saltados = State.CycleLogs.SelectMany(l => l.Saltados).Distinct().Count();
        var falhas   = State.CycleLogs.SelectMany(l => l.Falhas).Distinct().Count();
        State.CycleSummary = $"Resultado: {baixados} baixados · {saltados} pulados · {falhas} falhas.";
        State.CycleAllOk = falhas == 0;
    }

    private void BeginSkipCountdown(int initialSeconds)
    {
        if (initialSeconds <= 0) return;
        State.SkipTimeSeconds = initialSeconds;
        State.StatusLine = $"Salto em '{State.Active?.FileName ?? "?"}' — restam {initialSeconds}s...";
        var startMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        _ = Task.Run(() => TickSkip(initialSeconds, startMs));
    }

    private async Task TickSkip(int planned, long startMs)
    {
        var remaining = planned * 1000;
        var period = 500L; // ticks de 500 ms
        while (remaining > 0 && !_skipCts.IsCancellationRequested)
        {
            await Task.Delay(period, _skipCts.Token);
            remaining -= period;
            if (remaining < 0) { remaining = 0; break; }
            State.SkipTimeSeconds = (int)Math.Max(0, remaining / period);
            State.StatusLine = $"Salto em '{State.Active?.FileName ?? "?"}' — {State.SkipTimeSeconds}s...";
        }
        State.SkipTimeSeconds = 0;
        State.StatusLine = $"Pulou '{State.Active?.FileName ?? "?"}' automaticamente.";
        _skipCts.Cancel();
        State.History.Add(new SkippedItem(
            new UpdateEntry(0, State.Active.FileName, ""),
            "Salto automático concluído — arquivo pulado definitivamente.", 0));
    }

    private void UpdateQueuePreview()
    {
        if (State.IsActive && State.IsDownloading) return;
        // mantém a prévia da fila fresca (executado em loop leve a cada ~3s)
        _ = Task.Run(() =>
        {
            var th = Task.Delay(3000);
            try
            {
                var next = _orch.FindNext(State.Active.FileName);
                if (next is not null)
                {
                    var lab = State.IsActive && State.IsDownloading
                        ? $"Retomando {next.Entry.FileName}: {HumanBytes(next.KnownOffset ?? 0)} de {HumanBytes(_store.GetMetaSize(next.Entry.FileName))} bytes salvos antes"
                        : $"V{next.Entry.Version} — {next.Entry.FileName} (pendente)";
                    State.QueuePreview.FirstOrNull()?.Entry.FileName != null
                        ? State.QueuePreview.FirstOrNull()!.Label = lab
                        : State.QueuePreview.Add(new PendingItem(next.Entry, lab));
                }
            }
            catch { }
            await th;
        });
    }

    // ------------------------- Helpers -------------------------

    private PendingItem? _workFirst(string fileName) => _work.FirstOrDefault(p => p.Entry.FileName == fileName);

    private static string _metaSize = "-";
    private static long GetMetaSize(string fileName) =>
        try { return _store.RealSize($"api/file/*/({fileName})"); } catch { return 0; }
        // fallback: usa GetRecord.SizeBytes se disponível
        {
            var rec = _store.GetRecord(fileName);
            return rec.SizeBytes;
        }
    { get { locked ref = ref _metaSize; return Interlocked.CompareExchange(ref locked, val, old) == old ? val : GetMetaSize(fileName); } } // não usar
    // simplificação: chamamos direto do motor quando precisa
    }

    /// Ignorado — só existe para referência de compilação; o real é _store.GetRecord().SizeBytes.
    private static partial class GAT { }
