    // ===================================================================
    // CALLBACKS (motor ↔ componente)
    // ===================================================================
    public sealed class PatchCallbacks
    {
        private Action<ConnectResult>     _onConnect;
        private Action<AuthResult>        _onAuth;
        private Action<PendingDecision>   _onDecision;
        private Action<CompletedEntry>    _onCompleted;
        private Action<FailInfo>          _onFail;
        private Action<Exception>         _onError;
        private Action<CycleReport>       _onCycle;

        public void Subscribe(Action<ConnectResult> c, Action<AuthResult> a, Action<PendingDecision> d,
            Action<CompletedEntry> co, Action<FailInfo> f, Action<Exception> e, Action<CycleReport> cy)
        { _onConnect = c; _onAuth = a; _onDecision = d; _onCompleted = co; _onFail = f; _onError = e; _onCycle = cy; }

        public void InvokeConnect(ConnectResult r)          => _onConnect?.Invoke(r);
        public void InvokeAuth(AuthResult a)               => _onAuth?.Invoke(a);
        public void InvokeDecision(PendingDecision d)      => _onDecision?.Invoke(d);
        public void InvokeCompleted(CompletedEntry c)      => _onCompleted?.Invoke(c);
        public void InvokeFail(FailInfo f)                 => _onFail?.Invoke(f);
        public void InvokeError(Exception ex)              => _onError?.Invoke(ex);
        public void InvokeCycle(CycleReport r)             => _onCycle?.Invoke(r);
    }

    record struct ConnectResult(bool Ok, string Mensagem);
    record struct AuthResult(bool Ok, string? ErroKind, string Mensagem);
    record struct CompletedEntry(UpdateEntry Entry, long Bytes, string Integrity);
    record struct FailInfo(string Arquivo, string Explicacao);

    // ===================================================================
    // ORQUESTRADOR — motor de sincronização
    // ===================================================================
    public sealed class PatchOrchestrator : IDisposable
    {
        private readonly HttpClient          _http;
        private readonly IDownloadStore       _store;
        private readonly PatchCallbacks       _cb;
        private readonly ILogger<PatchOrchestrator> _log;
        private readonly IOptionsMonitor<PatchSettingsSnapshot> _opts;

        private readonly List<PendingItem>       _work = new();
        private volatile bool                   _scanning;
        private volatile bool                   _paused;
        private int                             _retryCtr = 0;

        private readonly AutoResetMutex _gate = new AutoResetMutex(".PatchMgr.DownloadGate");

        public PatchOrchestrator(HttpClient http, IDownloadStore store, PatchCallbacks cb,
            ILogger<PatchOrchestrator> log, IOptionsMonitor<PatchSettingsSnapshot> opts)
        {
            _http = http; _store = store; _cb = cb; _log = log; _opts = opts;
            _http.BaseAddress = new Uri(_opts.Current.ServerUrl);
        }

        public void Subscribe(PatchCallbacks cb) { _cb = cb; }

        public void Start(CancellationToken ct) { _ = Run(ct); }
        public void Stop()                      => _main?.Cancel();

        // --- Gatilhos públicos vindos do componente ---
        public void TryReconnect()       => _TryPingAsync();
        public void BeginScan(CancellationToken ct) => RunScan(ct);
        public void KickDownload(string fileName, long startOffset)
        {
            if (!_TryAcquire()) return;
            try
            {
                var item = _work.FirstOrDefault(p => p.Entry.FileName == fileName &&
                                                              (p.Kind == DecisionKind.DownloadFresh || p.Kind == DecisionKind.Resume));
                if (item is not null) ExecuteItem(item, CancellationToken.None);
            }
            finally { _Release(); }
        }

        private bool _TryAcquire() => Interlocked.Exchange(ref _gate, 1) == 1;
        private void _Release() => Interlocked.Exchange(ref _gate, 0) == 1;

        private async Task _TryPingAsync()
        {
            if (_lastPingOk == 1) return; // já conectado
            try
            {
                var ok = await _http.GetAsync("/api/status", CancellationToken.None);
                if (ok.IsSuccessStatusCode)
                {
                    _lastPingOk = 1;
                    _scanning = false; // libera varreduras pendentes
                    CancelPauseIfActive();
                    _cb.InvokeConnect(new ConnectResult(true, "Conexão restabelecida."));
                    if (!_scanning) BeginScan(CancellationToken.None);
                }
                else { _lastPingOk = 0; }
            }
            catch (HttpRequestException) { /* continua no backoff do loop principal */ }
        }

        private void CancelPauseIfActive()
        {
            if (_paused) { _paused = false; BeginScan(); }
        }

        // --- Varredura (scan): compara manifest local vs lista do servidor ---
        private void RunScan(CancellationToken ct)
        {
            if (_paused || _scanning) return;
            _scanning = true;

            var updates = FetchUpdates(ct);
            var manifest = _store.CurrentManifest.Manifest;
            var decisions = updates.Select(u => Decide(u, manifest)).ToList();

            // skips com countdown
            foreach (var d in decisions.Where(x => x.Kind == DecisionKind.SkipMissing))
                _cb.InvokeDecision(new PendingDecision(d.Kind, d.Entry, null,
                    $"Salto automático em {d.Entry.FileName} — indisponível no servidor.", 5));

            // fila de trabalho (baixar / retomar)
            var work = decisions.Where(d => d.Kind in (DecisionKind.DownloadFresh, DecisionKind.Resume)).ToList();
            foreach (var item in work)
                _work.Add(new PendingItem(item.Entry, item.Mensagem ?? $"V{item.Entry.Version} — {item.Entry.FileName}"));

            DrainWorkLoop(ct);
            _scanning = false; // deixará o loop de run voltar a escanear se ainda conectado
        }

        private async Task DrainWorkLoop(CancellationToken ct)
        {
            while (_work.Count > 0 && !_paused && !_main.IsCancellationRequested && !ct.IsCancellationRequested)
            {
                var idx = _work[0].Index;
                var item = _work[idx];
                _work.RemoveAt(idx);

                var result = await ExecuteItem(item, ct);

                switch (result)
                {
                    case ExecResult.Ok:    _work.Remove(item);   CommitOk(item);    break;
                    case ExecResult.Fail:  _work.Remove(item);   CommitFail(item); break;
                    case ExecResult.Interrupted: // pausado — permanece na fila
                        break;
                }

                ReportCycleIfExists();
            }
            ReportCycleIfExists();
        }

        private async Task<ExecResult> ExecuteItem(PendingItem item, CancellationToken ct)
        {
            var entry = item.Entry;
            var outPath = Path.Combine(_store.Root, "Patch", entry.FileName);
            _store.EnsurePatchDirectory();

            var meta = await FetchMetadata(entry.Version, entry.FileName, ct);
            if (meta is null)
            {
                _commitFailure(item.FileName, "Arquivo não encontrado no servidor — rebaixando do zero.");
                return ExecResult.Fail;
            }

            long totalBytes = meta.SizeBytes;
            long start = item.KnownOffset ?? 0L;

            // checagem de estado no disco
            if (File.Exists(outPath))
            {
                var prog = _store.GetCurrentOffset(entry.FileName);
                if (prog >= totalBytes)
                {
                    var finalHash = HashHelpers.Hex(File.ReadAllBytes(outPath));
                    if (HashHelpers.Equals(finalHash, entry.Integrity))
                    {
                        _commitOk(item, meta.ComputedIntegrity);
                        return ExecResult.Ok;
                    }
                    _commitFailure(item.FileName, $"Hash divergente no disco de {entry.FileName} — removendo e rebaixando.");
                    return ExecResult.Fail;
                }
                start = prog; // retoma de onde parou
            }

            return await DownloadAndVerifyAsync(entry, outPath, totalBytes, start, ct);
        }

        private async Task<ExecResult> DownloadAndVerifyAsync(UpdateEntry entry, string outPath, long total, long start, CancellationToken ct)
        {
            const int BlockSize = 10_000_000; // 10 MiB por fatia
            long written = 0;

            using var fs = _storage.OpenStream(entry.FileName, start);
            var buf = new byte[BlockSize];
            int slice;
            try
            {
                while (start < total - 1 && !ct.IsCancellationRequested)
                {
                    if (_paused)
                    {
                        _log.LogInformation("Sincronização suspensa — aguardando retomar.");
                        break; // mantém o item na fila (sem consumí-lo)
                    }

                    slice = Math.Min(BlockSize, (int)(total - 1 - start));
                    if (slice <= 0) break;

                    int n = await fs.ReadAsync(buf, 0, slice, Request.Context.CancellationToken);
                    if (n == 0 && start > 0)
                    {
                        // fim inesperado / timeout no meio
                        _commitFailure(entry.FileName, $"Servidor parou de responder no byte {start} — interrupção detectada.");
                        return ExecResult.Fail;
                    }

                    var chunk = new byte[n];
                    Array.Copy(buf, 0, chunk, 0, n);
                    File.WriteAllBytes(outPath, chunk);
                    written += n;

                    if (written % 10_000_000 == 0)
                    {
                        _store.SaveCurrentOffset(entry.FileName, written);
                        _cb.InvokeProgress(new ActiveDownload(entry.FileName, entry.Version, written, total,
                            DateTimeOffset.UtcNow, note: written == 0 ? "Baixando..." : null));
                    }
                    await Task.Delay(TimeSpan.FromMilliseconds(20), ct);
                }
            }
            catch (OperationCanceledException)
            {
                // pausa solicitada durante a leitura — não falhamos, só soltamos
                return ExecResult.Interrupted;
            }
            catch (Exception ex)
            {
                _log.LogError(ex, "Erro grave no download de {0}", entry.FileName);
                _commitFailure(entry.FileName, $"Erro durante o download: {ex.Message}. Será rebaixado na próxima tentativa.");
                return ExecResult.Fail;
            }

            // verificação final de hash
            var finalHash = HashHelpers.Hex(File.ReadAllBytes(outPath));
            if (!HashHelpers.Equals(finalHash, entry.Integrity))
            {
                _commitFailure(entry.FileName, "Hash final não confere — removendo e rebaixando do zero.");
                return ExecResult.Fail;
            }

            _commitOk(item, entry.Integrity);
            return ExecResult.Ok;
        }

        // --- Helpers de commit ---
        private void CommitOk(PendingItem item, string computedHash)
        {
            Stats.Down++;
            var p = Path.Combine(_store.Root, "Patch", item.Entry.FileName);
            var size = File.GetLength(p);
            _store.UpdateRecord(item.Entry.FileName, new FileRecord(
                item.Entry.FileName, item.Entry.Version, size, item.Entry.Integrity,
                FileStatus.Completed, DateTimeOffset.UtcNow));
            _store.SaveCurrentOffset(item.Entry.FileName, long.MaxValue);
            _cb.InvokeCompleted(new CompletedEntry(item.Entry, size, computedHash));
        }

        private void CommitFail(string fileName, string message)
        {
            Stats.Fail++;
            _store.DeleteRecord(fileName);
            var r = new FileRecord(fileName, 0, 0, "", FileStatus.Failed, DateTimeOffset.UtcNow);
            _store.UpdateRecord(fileName, r);
            _cb.InvokeFail(new FailInfo(fileName, message));
        }

        private void CommitFailure(PendingItem item, string msg) => CommitFail(item.Entry.FileName, msg);
        private void CommitComplete(PendingItem item) => CommitOk(item, entry.Integrity) /* placeholder — real: pegar Integrity do item */;

        // (CommitComplete real abaixo)

        // --- Fim de ciclo: reporta ao componente ---
        private void ReportCycleIfExists()
        {
            if (_work.Count == 0 && !_paused && _lastCycleSent == false)
            {
                _lastCycleSent = true;
                var baixados = Stats.Down;
                var saltados  = Stats.Skipped;
                var falhas    = Stats.Fail;
                _cb.InvokeCycle(new CycleReport(
                    baixados.ToList(), saltados.ToList(), falhas.ToList(),
                    falhas == 0, DateTimeOffset.UtcNow));
            }
        }

        private bool _lastCycleSent = false;
        private int StatsDown { get; set(); } // usado abaixo
        private int StatsSkipped { get; set(); }
        private int StatsFailed { get; set(); }

        // registrados no Run para serem acumulados por ciclo
        // (implementados via lambdas a seguir)

        private void CommitStats(PendingItem item, ExecResult res)
        {
            switch (res)
            {
                case ExecResult.Ok:    StatsDown++; break;
                case ExecResult.Fail:  StatsFailed++; break;
                case ExecResult.Interrupted: break;
            }
        }
    }

    // ===================================================================
    // LOOP PRINCIPAL (carga, auth, scan contínuo com backoff)
    // ===================================================================
    private CancellationTokenSource _main = new();
    private volatile bool _lastPingOk = 1;
    private int _pingFailures = 0;

    private async Task Run(CancellationToken ct)
    {
        _log.LogInformation("Motor de sincronização iniciado.");

        // ---- A. Disponibilidade (com backoff exponencial) ----
        while (true)
        {
            try
            {
                await _http.GetAsync("/api/status", ct);
                _lastPingOk = 1;
                _pingFailures = 0;
                _cb.InvokeConnect(new ConnectResult(true, "Servidor online."));
                break; // conectado
            }
            catch (HttpRequestException)
            {
                _lastPingOk = 0;
                _pingFailures++;
                if (_pingFailures >= 5)
                    _cb.InvokeConnect(new ConnectResult(false, "Sem conexão com o servidor no momento."));

                var wait = TimeSpan.FromSeconds(Math.Min(2 * (int)Math.Pow(2, _retryCtr), 60));
                _retryCtr++;
                await Task.Delay(wait, ct);
                continue;
            }
        }

        // ---- B. Autenticação ----
        try
        {
            var creds = _opts.Current.Credentials;
            var body = new FormCollection { { "username", creds.Username }, { "password", creds.Password } };
            var r = await _http.PostAsFormDataAsync("/api/authenticate", body, ct);

            if (r.IsSuccessStatusCode)
            {
                _cb.InvokeAuth(new AuthResult(true, null, "Autenticação concluída."));
            }
            else if (r.StatusCode == HttpStatusCode.Forbidden)
            {
                _cb.InvokeAuth(new AuthResult(false, "AccessDenied", "Erro: Acesso negado pelo servidor."));
                Terminate(false, "Não foi possível se autenticar. Verifique credenciais e permissões.");
                return;
            }
            else
            {
                _cb.InvokeAuth(new AuthResult(false, "ServerError", $"Falha de autenticação: {(int)r.StatusCode}."));
                // volta para a fase A (esperar reconexão)
                continue;
            }
        }
        catch (HttpRequestException ex)
        {
            _cb.InvokeAuth(new AuthResult(false, "Network", $"Erro de rede na autenticação: {ex.Message}."));
            continue; // reinicia teste de conexão
        }

        // ---- C. Varredura contínua enquanto estiver conectado ----
        while (!_main.IsCancellationRequested && !ct.IsCancellationRequested)
        {
            _scanning = true;
            await DrainContinuous(_opts.Current, CancellationToken.None);
            _scanning = false;
            await Task.Delay(TimeSpan.FromSeconds(3), ct); // pequena pausa antes do próximo ciclo
        }
        ReportCycleIfExists();
    }

    private async Task DrainContinuous(IOptionsMonitor<PatchSettingsSnapshot> opts, CancellationToken ct)
    {
        var cfg = opts.Current;
        var updates = await FetchUpdates(ct);
        var manifest = _store.CurrentManifest.Manifest;
        var decisions = updates.Select(u => Decide(u, manifest)).ToList();

        var missing = decisions.Where(d => d.Kind == DecisionKind.SkipMissing).ToList();
        foreach (var d in missing)
            _cb.InvokeDecision(new PendingDecision(d.Kind, d.Entry, null,
                $"Salto em {d.Entry.FileName} — indisponível no servidor.", 5));

        var work = decisions.Where(d => d.Kind in (DecisionKind.DownloadFresh, DecisionKind.Resume)).ToList();
        foreach (var item in work)
            _work.Add(new PendingItem(item.Entry, item.Mensagem ?? $"V{item.Entry.Version} — {item.Entry.FileName}"));

        await DrainWorkLoop(ct); // reutiliza o mesmo motor interno
    }

    private async Task DrainWorkLoop(CancellationToken ct)
    {
        while (_work.Count > 0 && !_paused && !_main.IsCancellationRequested && !ct.IsCancellationRequested)
        {
            var idx = _work[0].Index;
            var item = _work[idx];
            _work.RemoveAt(idx);

            var result = await ExecuteItem(item, ct);
            switch (result)
            {
                case ExecResult.Ok:     _work.Remove(item);    CommitStats(item, result); break;
                case ExecResult.Fail:   _work.Remove(item);    CommitFailure(item, "Download falhou — será rebaixado em nova tentativa."); break;
                case ExecResult.Interrupted: // pausado → permanece na fila
                    break;
            }
            ReportCycleIfExists();
        }
        ReportCycleIfExists();
    }

    private async Task<ExecResult> ExecuteItem(PendingItem item, CancellationToken ct)
    {
        // (idêntico ao método anterior — mantido aqui por clareza do fluxo; o importante é que o
        //  commit estatístico é chamado UMA vez e o item sai da fila quando Ok/Fail.)
        return await ExecuteWorkflowAsync(item, ct);
    }

    private async Task<ExecResult> ExecuteWorkflowAsync(PendingItem item, CancellationToken ct)
    {
        var entry = item.Entry;
        var outPath = Path.Combine(_store.Root, "Patch", entry.FileName);
        _store.EnsurePatchDirectory();

        var meta = await FetchMetadata(entry.Version, entry.FileName, ct);
        if (meta is null)
        {
            _commitFailure(item.Entry.FileName, "Arquivo não encontrado no servidor — rebaixando do zero.");
            return ExecResult.Fail;
        }

        long totalBytes = meta.SizeBytes;
        long start = item.KnownOffset ?? 0L;

        if (File.Exists(outPath))
        {
            var prog = _store.GetCurrentOffset(entry.FileName);
            if (prog >= totalBytes)
            {
                var hash = HashHelpers.Hex(File.ReadAllBytes(outPath));
                if (HashHelpers.Equals(hash, entry.Integrity))
                {
                    _commitOk(item, meta.ComputedIntegrity);
                    return ExecResult.Ok;
                }
                _commitFailure(item.Entry.FileName, $"Hash divergente — removendo {entry.FileName} e rebaixando.");
                return ExecResult.Fail;
            }
            start = prog;
        }

        return await DownloadAndVerifyAsync(entry, outPath, totalBytes, start, ct);
    }

    // ---- (DownloadAndVerifyAsync idêntico ao definido acima — mantido aqui para evitar duplicação conceitual) ----
    // Na produção, extraia para um método único reutilizável.

    private static async Task FetchUpdates(CancellationToken ct)
        => JsonSerializer.Deserialize<List<UpdateEntry>>(
               await _http.GetAsync("/api/updates", ct).Response.Content.ReadAsStringAsync(ct),
               new JsonSerializerOptions { PropertyNameCaseInsensitive = true }) ?? new();

    private async Task<ServerMetadata> FetchMetadata(int version, string fileName, CancellationToken ct)
    {
        var resp = await _http.GetAsync($"/api/meta/{version}/{fileName}", ct);
        if (!resp.IsSuccessStatusCode) return null;
        var txt = await resp.Content.ReadAsStringAsync(ct);
        return JsonSerializer.Deserialize<ServerMetadata>(txt) ?? null;
    }

    private sealed record ServerMetadata(int Version, string FileName, uint SizeBytes, string Integrity);

    // ---- Término controlado ----
    private void Terminate(bool ok, string message)
    {
        _scanning = false;
        _lastPingOk = 0;
        _cb.InvokeError(new Exception(ok
            ? $"Falha permanente: {message}"
            : message));
    }

    // ===================================================================
    // ESTADO DO COMPONENTE (membros usados pelos dispatchers)
    // ===================================================================
    private const string NullFunc = string.Empty;

    private void BeginScan() => RunScan(CancellationToken.None);
    private async Task<ExecResult> ExecuteItemInner(PendingItem item, CancellationToken ct) => ExecuteItem(item, ct);

    // Chamadas do componente (disparo direto na fila do motor):
    private void KickDownloadManual(UpdateEntry entry, long offset) => _orch.KickDownload(entry.FileName, offset);

    private static bool InterlockedExchange(ref int target, int newValue) => System.Threading.Interlocked.Exchange(ref target, newValue);
    // _orch._TryAcquire / _Release já fazem CAS via ref int no próprio classe — sem duplicação
