// src/Domain/Models/PatchEntry.cs
using System.Security.Cryptography;
using System.Text;

namespace MyApp.Domain.Models;

/// <summary>
/// Entrada de uma atualização de patch fornecida pelo servidor.
/// Representa a estrutura parecida com a sua lista "patch.lua".
/// </summary>
public sealed record UpdateEntry(int Version, string FileName, string Integrity);

/// <summary>
/// Helper de hash. No exemplo usamos SHA-256 — mude para o algoritmo
/// exato usado pelo seu servidor (senão a verificação de hash nunca bate).
/// </summary>
public static class HashHelpers
{
    public static byte[] Digest(byte[] data) => SHA256.HashData(data, null);

    /// <summary>SHA-256 em hex maiúsculo.</summary>
    public static string Hex(byte[] data) => Convert.ToHexString(Digest(data));

    /// <summary>
    /// Compara dois hashes hex (SHA-256). Se os dois lados geram o mesmo valor
    /// para o mesmo arquivo, o download é considerado íntegro.
    /// </summary>
    public static bool Equals(string localHex, string expectedHex, bool caseInsensitive = true)
    {
        if (string.IsNullOrWhiteSpace(localHex) || string.IsNullOrWhiteSpace(expectedHex))
            return false;
        var lhs = caseInsensitive ? localHex.Trim().ToUpperInvariant() : localHex.Trim();
        return lhs.Equals(expectedHex.Trim().ToUpperInvariant(), StringComparison.Ordinal);
    }
}
