## 3. Servidor (backend mínimo — ASP.NET Core)

### 3.1 Armazenamento + streaming de arquivos com Range (permite baixar fatiado = resume real)

```csharp
// src/Services/PatchStorage.cs
using System.IO;
using System.Net;
using System.Security.Cryptography;
using System.Text;
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.Logging;

namespace MyApp.Services;

public interface IPatchStorage
{
    Stream OpenStream(string fileName, long offset); // streaming direto, respeita faixas (~10 MiB por faixa)
    long RealLength(string fileName);
    Metadata GetMetadata(UpdateEntry entry);
}

public sealed record Metadata(int Version, string FileName, uint SizeBytes,
    string DeclaredIntegrity, string ComputedIntegrity, bool IsValid);

public sealed class LocalPatchStorage : IPatchStorage
{
    private readonly string _patchRoot;
    private readonly ILogger<LocalPatchStorage> _log;

    public LocalPatchStorage(string patchRoot, ILogger<LocalPatchStorage> log)
    {
        _patchRoot = Path.EnforceTrailingSlash(patchRoot);
        _log = log;
        if (!Directory.Exists(_patchRoot)) Directory.CreateDirectory(_patchRoot);
    }

    public Stream OpenStream(string fileName, long offset)
    {
        var path = Path.Combine(_patchRoot, fileName);
        if (!File.Exists(path))
            throw new FileNotFoundException($"Arquivo inexistente: {path}");
        var fs = new FileStream(path, FileMode.Open, FileAccess.ReadWrite, ShareMode.ReadWrite);
        var realEnd = fs.Length - 1;
        var end = Math.Min(offset + 10_485_760L, realEnd); // teto de 10 MiB por faixa (evita 1 requisição gigante)
        if (end <= offset) fs.Close();
        else
        {
            fs.Seek(offset, SeekOrigin.Begin);
            fs.Close(); // deixa o descritor aberto; o cliente faz o ReadAsync da faixa
            return fs; // retorna para o cliente ler apenas a faixa solicitada
        }
    }

    public long RealLength(string fileName)
    {
        var p = Path.Combine(_patchRoot, fileName);
        if (File.Exists(p)) return File.GetLength(p);
        return -1;
    }

    public Metadata GetMetadata(UpdateEntry entry)
    {
        var path = Path.Combine(_patchRoot, entry.FileName);
        if (!File.Exists(path)) return MetadataNotFound(entry.FileName);

        using var sha = new SHA256Managed();
        using var fs = new FileStream(path, FileMode.Open, FileAccess.Read, ShareMode.ReadWrite);
        var hs = new MemoryStream();
        long pos = 0;
        var chunk = 4_000_000;
        byte[] b = new byte[chunk];
        while (pos < File.GetLength(path))
        {
            int nr = fs.Read(b, 0, chunk);
            if (nr == 0) break;
            sha.Update(b, 0, nr);
            hs.Write(b, 0, nr);
            pos += nr;
        }
        fs.Dispose();
        var hex = Convert.ToHexString(sha.Hash);

        return new Metadata(entry.Version, entry.FileName, (uint)File.GetLength(path),
            entry.Integrity, hex, HashHelpers.Equals(hex, entry.Integrity));
    }

    private static Metadata MetadataNotFound(string fileName)
        => new Metadata(0, fileName, 0, "", "", false);
}
```

### 3.2 Controller

```csharp
// src/Services/DownloadApi.cs
using System.Net;
using System.Net.Http.Headers;
using Microsoft.AspNetCore.Mvc;

namespace MyApp.Services;

[ApiController]
[Route("api/[controller]")]
public sealed class DownloadApi : ControllerBase
{
    private readonly IPatchStorage _storage;
    private readonly ILogger<DownloadApi> _log;

    public DownloadApi(IPatchStorage storage, ILogger<DownloadApi> log) { _storage = storage; _log = log; }

    /// <summary>Saúde — usada para detectar "servidor vivo" (base do reinício automático).</summary>
    [HttpGet("status")]
    public IActionResult Status() => Ok(new { online = true });

    /// <summary>Lista de updates (vem da sua fonte: banco, JSON do launcher, etc.)</summary>
    [HttpGet("updates")]
    public async Task<IActionResult> Updates()
    {
        var list = await UpdateSource.GetUpdatesAsync(); // sua implementação
        return Ok(list);
    }

    /// <summary>
    /// Autenticação. 200 = OK. 403 (Forbidden) = AccessDenied para o cliente mapear.
    /// Outras falhas de rede/5xx = ServerUnavailable (retry automático).
    /// </summary>
    [HttpPost("authenticate")]
    public IActionResult Authenticate([FromForm] AuthenticateDto dto)
    {
        try
        {
            if (ValidarUsuarioSenha(dto.Username, dto.Password)) return Accepted();
            return Forbid();
        }
        catch (UnauthorizedAccessException)
        {
            // SO negou acesso (ex.: pasta protegida)
            return Forbid();
        }
    }

    private static bool ValidarUsuarioSenha(string usuario, string senha)
    {
        // Placeholder: substitua pela validação real (banco / JWT que o launcher te entrega).
        return usuario.Equals("DEMO", StringComparison.OrdinalIgnoreCase) && senha.Equals("DEMO", StringComparison.OrdinalIgnoreCase);
    }

    /// <summary>
    /// Entrega o binário em faixas (Accept-Ranges). Sem Range e com offset > 0 → 426.
    /// Isso é o que torna o "continuar de onde parou" realmente funcional: cada fatia
    /// é lida direto do disco, sem carregar o arquivo inteiro em memória no servidor.
    /// </summary>
    [HttpGet("file/{version}/{fileName}")]
    [AcceptRanges("bytes")]
    public async Task<IActionResult> StreamFile(int version, string fileName, [FromQuery] long offset = 0)
    {
        if (!Request.Headers.AcceptRanges.Contains("bytes") && offset > 0)
            return StatusCodes.Status426RequirementUnmet();

        try
        {
            var stream = _storage.OpenStream(fileName, offset);
            var realEnd = stream.Length - 1;
            var endSlice = Math.Min(offset + 10_485_760L, realEnd);
            var sliceLen = (int)(endSlice - offset + 1);

            using var body = new MemoryStream();
            int n;
            while (body.Length < sliceLen)
            {
                n = await stream.ReadAsync(new byte[sliceLen], body.Length, sliceLen - body.Length,
                    Request.Context.CancellationToken);
                if (n == 0) break; // fim do arquivo antes do esperado
                body.Write(new byte[n], 0, n);
            }
            stream.Dispose();
            var content = body.CreateReadStream();

            return Ok(content, "application/octet-stream")
                .WithHeaders(new HeaderValues
                {
                    ["Content-Range"] = $"{offset}-{endSlice}/{_storage.RealLength(fileName)}",
                    ["Content-Length"] = body.Length.ToString(),
                    ["Accept-Ranges"] = "bytes",
                    ["Cache-Control"] = "no-cache, no-transform, must-revalidate",
                    ["X-Accel-Buffering"] = "no",
                });
        }
        catch (FileNotFoundException)
        {
            _log.LogWarning("Arquivo ausente no servidor: {0}", fileName);
            return NotFound(); // o cliente interpreta isso como "não existe → saltar"
        }
    }
}

public sealed record AuthenticateDto(string Username, string Password);
```

> **Detalhes de integração:** registre `DownloadApi` + `LocalPatchStorage` no DI do seu `Program.cs`, aponte `IPatchStorage.Root` para a pasta desejada (ex.: `%APPDATA%\...` ou a pasta do `.exe`) e configure origem CORS para a origem do Blazor. A fonte dos `/api/updates` é um dado seu (banco, JSON do launcher…); trate-o como a lista equivalente ao seu `patch.lua`.

