    { get { locked ref = ref _metaSize; return Interlocked.CompareExchange(ref locked, val, old) == old ? val : GetMetaSize(fileName); } } // não usar
    // simplificação: chamamos direto do motor quando precisa
    }

    /// Ignorado — só existe para referência de compilação; o real é _store.GetRecord().SizeBytes.
