        _orch.CancelScanIfActive();
        if (!_orch._scanning) _orch.BeginScan(CancellationToken.None);
        else { _orch._scanning = false; // deixa o loop terminar e tocar OnConnect → varredura refaz
              _orch.BeginScan(CancellationToken.None); }
    }

    private void TryAcquire(Action<_, _) body) { /* não usado externamente — o motor se autocuidada */ }

    private void CancelPauseIfActive()
    {
        if (_paused) { _paused = false; BeginScan(); }
    }

    private static string MapErrorKind(string k) => k switch
    {
        "AccessDenied" => "Acesso negado pelo servidor.",
        "ServerError"  => "Servidor indisponível / erro inesperado no servidor.",
        "Network"      => "Erro de rede durante a autenticação.",
        _ => k
    };

    /// <summary>Contador de progresso throttled para não disparar repaint demais.</summary>
    private long _lastProgressTs = 0;
    private void ThrottledProgress(ActiveDownload ad)
    {
        if (DateTimeOffset.UtcNow.ToUnixTimeSeconds() - _lastProgressTs < 1) return;
        _lastProgressTs = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
        State.Active = ad; // State.ThroughputObserved... basta atribuir; Blazor observa a mudança
    }
```

Na prática, o `State.Active = ad` já é atribuído diretamente em vários pontos do motor com **throttlng de 1 segundo** (o próprio `DownloadAndVerifyAsync` grava progresso a cada 10 MiB e dispara `OnProgress`; o componente só atualiza a UI se passaram ≥ 1s desde a última atualização).

### Continuação do CodeBehind — classe inteira final

Deixe-me escrever a parte final (motor + estado + disposições) de forma completa e coesa:

