    private async Task RunMainFlow(CancellationToken ct)
    {
        try
        {
            // 1. conectividade + autenticação
            State.Status = DownloadStatus.Connecting;
            State.StatusLine = "Conectando ao servidor...";
            await CheckReachability(ct);
            if (HasError) return;

            State.Status = DownloadStatus.Authenticating;
            State.StatusLine = "Autenticando no servidor...";
            await Authenticate(ct);
            if (HasError) return;

            State.Status = DownloadStatus.Preparing;
            State.StatusLine = "Preparando para iniciar o download...";
            await PrepareChecks(ct);
            await PerformNextAction(ct);
            await PerformNextAction(ct); // loop enquanto houver tarefas
        }
        catch (Exception ex) { HandleGlobalError(ex); await _retryLoop(); }
    }

    /// --- Reconectividade ---
    private async Task _retryLoop()
    {
        while (State.IsRetryingConnection || State.Status == DownloadStatus.Error && State.ErrorKind == "ServerUnavailable")
