```csharp
private void StartCountdown(int initial, CancellationToken ct)
{
    if (initial <= 0) return;
    State.SkipSecondsLeft = initial;
    State.IsSkipping = true;
    State.SkipMessage = $"Saltando '{State.FileName}' em ..." ; // hmm name dynamic
    var t = Task.Run(() =>
    {
        var elapsed = TimeSpan.FromMilliseconds(DateTime.UtcNow - checkedAtUtc); // use DateTimeOffset
        var remain = Math.Max(0, (int)((initial * 1000 - elapsed.TotalMilliseconds) / 200));
        State.SkipSecondsLeft = remain;
        if (remain <= 0) { State.IsSkipping = false; State.SkipMessage = string.Empty; }
        Thread.Sleep(200); // reaplicar
    });
    // não precisa capturar; termina sozinho quando =0 e remove a propriedade
    _ = t; // background, pode ser cancelado
}
```

