```csharp
private async Task<PatchCycleResult> RunCycle(CancellationToken ct)
{
    var result = new PatchCycleResult { Started = DateTime.UtcNow };
    var state = new DownloadStateSnapshot { Files = new Dictionary<string, Pending>(), Connected = false, ErrorKind = "", ErrorMessage = "" };

    // ---- CONECTAR E AUTENTICAR (etapa única, pode repetir após desconexão) ----
    for (; ; )
    {
        try
        {
            var rc = await CheckAndLogin(ct);
            if (rc.Ok)
            {
                _Invoke(_callbacks?.OnConnect ?? x => {}, new OnConnectResult(true, "Servidor respondendo normalmente."));
                state.Connected = true; state.LastError = null;
                break;
            }
            if (rc.Kind == AccessDenied)
            {
                _Invoke(_callbacks?.OnError ?? x => {}, $"Acesso negado ({(int)rc.StatusCode})");
                return result; // terminamos: não dá para prosseguir
            }
            if (rc.Kind == ServerUnavailable)
            {
                if (!_callbacks?.OnRetry ?? (x => {}).Invoke()) break; // usuário aceita aguardar
                _log.LogWarning("Servidor indisponível, aguardando reconexão...");
                await Task.Delay(RandomDuration(ct));
                continue;
            }
            _Invoke(_callbacks?.OnError ?? x => {}, $"Erro inesperado: {(string)rc.Kind}");
            return result;
        }
        catch (HttpRequestException)
        {
            // Timeout/DNS/etc.
            _Invoke(_callbacks?.OnError ?? (k,m)=>{}, $"Indisponível: {exception.Message}");
            await Task.Delay(RandomDuration(ct));
            continue;
        }
    }

    // ---- ESCANEAR O QUE FALTA (usa lista de updates do servidor) ----
    var updates = await FetchUpdates(ct);
    var manifest = _store.RefreshManifest();
    foreach (var entry in updates)
    {
        var p = manifest.Files.GetValueOrDefault(entry.FileName) ?? new Pending { Entry = entry };
        var decision = await EvaluateDecision(p, entry, ct);
        p.Decision = decision;
        if (decision == Decision.SkipAlreadyGood)
            _Invoke(_callbacks?.OnSkip ?? (e,r)=>{}, e, r);
        else if (decision == Decision.SkipMissing)
        {
            // agendar countdown
            _Invoke(_callbacks?.OnError ?? (k,m)=>{$"Arquivo {e.FileName} não encontrado – salto em 5 segundos…"}, null); // conta o próprio timer
            ScheduleSkip(entry, 5, ct);
        }
        else if (decision == Decision.ResumeOrDownload)
            EnqueueDownload(entry, p.KnownOffset, p.Total, ct);
        else if (decision == Decision.AlreadyDone)
            _Invoke(_callbacks?.OnDone ?? (f,b,i)=>{}, f, b, i);
    }

    // processar downloads do lote atual (sequencial)
    var jobs = state.PendingWhere(d => d.Decision == DownloadPending).ToList();
    foreach (var job in jobs)
    {
        var done = await DownloadJob(job, ct);
        if (done is DownloadResult.Ok { Verified: true })
        {
            _Invoke(_callbacks?.OnDone ?? (f,b,i)=>{}, job.Entry.FileName, b, i);
        }
        else if (done is DownloadResult.Failed)
            _Invoke(_callbacks?.OnFail ?? (f,e)=>{}, job.Entry.FileName, e);
        // InProgress permanece na fila (poderá ser retomado)
    }

    // reavaliar (alguns podem agora estar prontos, outros pendentes)
    state.RewatchManifest();
    // tentar reconectar de novo se desligamos
    var stillOffline = !state.Connected;
    if (stillOffline)
    {
        for (var i = 0; i < 10; i++)
        {
            try { var ok = await CheckReachability(ct); if (ok) { state.Connected=true; break; } await Task.Delay(random, ct); }
            catch { await Task.Delay(random, ct); }
        }
        if (!state.Connected)
            _Invoke(_callbacks?.OnError ?? (_,m)=>{$"Perdeu a conexão; sincronização suspensa. Reinicie o aplicativo para retomar."}, m);
    }

    var final = new PatchCycleResult { Result = ProcessFinalState(state), Started = result.Started };
    _Invoke(_callbacks?.OnCycleEnd ?? r=>{}, final);
    return final;
}
