```csharp
public sealed class SyncScheduler : IDisposable
{
    private readonly HttpClient _http;
    private readonly IDownloadStore _store;
    private readonly IEnumerable<EventHandler> _handlers;
    private readonly string _baseUrl;
    private CancellationTokenSource _cts = new();
    private DateTime _now;
    private HashSet<string> _online = new();

    public SyncScheduler(HttpClient http, IDownloadStore store, IEnumerable<EventHandler> handlers, IConfiguration cfg)
    { _http=http; _store=store; _handlers=list(handlers); _baseUrl=cfg["DownloadServerBaseUrl"]??"..."; }

    public void Start() => Run(_cts.Token).ConfigureAwait(false);
    public void Stop() => _cts.Cancel();

    private async Task Run(CancellationToken ct)
    {
        var done = false;

        // ===== 1. conectar + autenticar (com retry de reconexão) =====
        while (!done)
        {
            var ready = await EnsureOnline(ct);
            if (ready) { done = true; break; }
            // erro temporário → pausa e espera
            await PollBackoff(ct);
        }

        // ===== 2. listar updates =====
        var updates = await FetchUpdates(ct);
        if (updates.Count == 0) { LogInfo("Nenhum update disponível."); return; }

        var manifest = _store.RefreshManifest();

        // ===== 3. avaliar cada entry =====
        var toSkipByHash = new List<(UpdateEntry e, string raz)>();
        var toDownload = new List<DownloadPlan>(); // entrada + offset conhecido
        var toSkipMissing = new List<UpdateEntry>(); // vai pro countdown

        foreach (var u in updates)
        {
            var m = manifest.Files.GetValueOrDefault(u.FileName);
            var info = m?.Status switch
            {
                Done => CheckHash(m, u) == Ok ? toSkipByHash : (toDownload.WithOffset(m?.LastSaved ?? 0)), // parcial → resume
                Skipped => toSkipMissing, // foi pulado antes; reavaliar
                _ => _ => null // não registrado
            };
            // decidir:
            if (info is SkipOk {}) { toSkipByHash.Add(u); continue; }
            if (m?.Status == MissingEquivalent) { toSkipMissing.Add(u); continue; } // heuristic: se existe progress_vazio e hash inválido? complica; trata como faltante
            // caso: arquivo existe mas hash não bate → baixa
            // caso: sem registro → falta → baixa
            ...
        }

        // ===== 4. executar plano =====
        foreach (var plan in toSkipMissing)
        {
            ScheduleSkip(plan, 5);
        }
        await ExecuteQueue(toDownload, ct);

        // reconecta se ficou offline durante execução
        ...
        // salva resultado final no manifest
    }

    // ... helpers: EnsureOnline (ping), PollBackoff, ScheduleSkip (countdown callback), Evaluate, DownloadWithResume, Verify, SaveManifest, CheckHashLocal
}
```

