public sealed class LocalPatchStorage : IPatchStorage
{
    private readonly IWebHostEnvironment _env;
    private readonly string _root;

    public LocalPatchStorage(IWebHostEnvironment env, string root)
    {
        _env = env;
        _root = Path.EnforceTrailingSlash(root);
    }

    public Stream GetStream(string fileName) =>
        new FileStream(Path.Combine(_root, "Patch", fileName), FileMode.Open, FileAccess.Read, share: ShareMode.ReadWrite);

    public Stream GetRemainingStream(string fileName, int startOffset, long totalBytes)
    {
        var path = Path.Combine(_root, "Patch", fileName);
        if (!File.Exists(path)) throw new FileNotFoundException($"Não encontrado: {path}");
        using var fs = new FileStream(path, FileMode.Open, FileAccess.ReadWrite, share: ShareMode.ReadWrite, FileOptions.RetainFileReferences);
        // garante que não leia além do tamanho real do arquivo
        var realLen = fs.Length;
        // Se quem chama enviou totalBytes errado, limita à realidade (cliente recebe faixa correta)
        var limit = Math.Min(totalBytes, realLen - startOffset);
        if (limit <= 0) throw new InvalidOperationException("Offset inválido para este arquivo.");
        return new FileStream(fs, FileMode.Open, FileAccess.Read, share: ShareMode.ReadWrite, leaveOpen: true);
        // leaveOpen=true permite ler enquanto cliente grava; fechamos depois? leaveOpen deixa aberto — uso com Dispose do stream do cliente. Preferir deixar aberto: não fechar. OK.
    }
```

