// ---------------------------------------------------------------
// PatchOrchestrator (motor de controle)
// ---------------------------------------------------------------
public sealed class PatchOrchestrator : IDisposable
{
    private readonly HttpClient _http;
    private readonly IDownloadStore _store;
    private readonly string _baseUrl;
    private readonly ICallbacks _callbacks;
    private readonly ILogger<PatchOrchestrator> _log;
    private readonly CancellationTokenSource _cts = new();
    private Task<None> _loop;

    public PatchOrchestrator(HttpClient http, IDownloadStore store, ICallbacks callbacks, ILogger<PatchOrchestrator> log, IConfiguration cfg)
    {
        _http = http;
        _store = store;
        _callbacks = callbacks;
        _log = log;
        _baseUrl = cfg["DownloadServerBaseUrl"] ?? "https://hil-speed.hetzner.com";
        _http.BaseAddress = new Uri(_baseUrl);
    }

    public void Subscribe(Action<OnConnected> onConnect, Action<OnDisconnected> onDisconnect, Action<string, string> onError,
                          Action<OnSkipRequested> onSkip, Action<OnResuming> onResume, Action<OnCompleted> onComplete, Action<PatchCycleReport> onCycleEnd)
    {
        _callbacks.OnConnected = onConnect;
        _callbacks.OnDisconnected = onDisconnect;
        _callbacks.onError = onError;
        _callbacks.OnSkip = onSkip;
        _callbacks.OnResuming = onResume;
        _callbacks.OnCompleted = onComplete;
        _callbacks.OnCycleEnd = onCycleEnd;
    }

    public void Start() => _loop = Run(_cts.Token);
    public void Stop() => _cts.Cancel();

    private async Task Run(CancellationToken ct)
    {
        _log.LogInformation("Motor de sincronização iniciado.");

        // === Bloco A: disponibilidade + autenticação (com backoff) ===
        while (true)
        {
            try
            {
                _log.LogInformation("Testando conexão...");
                var ping = await _http.GetAsync("/api/status", ct);
                if (ping.IsSuccessStatusCode)
                {
                    _callbacks.OnConnected.Invoke(true, "Servidor conectado.");
                    break;
                }
                // 403/5xx/erro de rede → reconectar depois
                _log.LogWarning("Ping falhou: {(int)ping.StatusCode}");
                var wait = TimeSpan.FromMilliseconds(Random.Shared.Next(3000, 15000)); // cuidado Random.Shared multithread — usar campo privado
                await Task.Delay(wait);
                continue;
            }
            catch (HttpRequestException ex)
            {
                _log.LogError(ex, "Falha de rede ao testar servidor.");
                await BackoffRetry(ct, 30_000);
                continue;
            }
        }

        // === Bloco B: autenticar ===
        _log.LogInformation("Autenticando no servidor...");
        try
        {
            var creds = GetCredentials(); // usuário/senha configurados
            var auth = await _http.PostAsFormDataAsync("/api/authenticate", creds, ct);
            if (auth.IsSuccessStatusCode)
            {
                _callbacks.OnConnected.Invoke(true, "Autenticação concluída.");
            }
            else if (auth.StatusCode == HttpStatusCode.Forbidden)
            {
                _callbacks.onError.Invoke("AccessDenied", "Erro: Acesso negado pelo servidor.");
                return Terminar(false, $"Não foi possível se autenticar. Verifique suas credenciais no painel do launcher.");
            }
            else
            {
                _callbacks.onError.Invoke("AuthFailed", $"Falha de autenticação: {(int)auth.StatusCode}.");
                return Terminar(false, "Falha na autenticação. Tente novamente mais tarde.");
            }
        }
        catch (HttpRequestException ex)
        {
            _callbacks.onError.Invoke("Network", $"Erro de rede durante a autenticação: {ex.Message}.");
            await BackoffRetry(ct, 5_000);
            continue; // volta ao loop de ping
        }

        // === Bloco C: verificar o que falta nos updates ===
        _log.LogInformation("Levantando pendências de atualização...");
        var updates = await FetchUpdates(ct);
        var manifest = _store.LoadManifest();
        var decided = new List<PendingDecision>();

        foreach (var entry in updates)
        {
            var record = _store.GetRecord(entry.FileName);
            var decision = Decide(entry, manifest, record, ct);
            decided.Add(decision);
        }

        // executar skip countdowns
        foreach (var d in decided.Where(x => x.Kind == Kind.SkipMissing))
        {
            _callbacks.OnSkip.Invoke(d.Entry, "Arquivo não encontrado no servidor.", 5);
        }

        // baixar / retomar
