    private async Task BackoffRetry(CancellationToken ct, int baseMs)
    {
        var attempts = 0;
        while (attempts < 8)
        {
            var wait = TimeSpan.FromMilliseconds(baseMs * (int)Math.Pow(2, attempts));
            _log.LogInformation("Retentando em {0} ms...", wait.TotalMilliseconds);
            await Task.Delay(wait, ct);
            attempts++;
            try { break; } catch { /* continuar */ }
        }
    }

    /// Decide qual ação tomar para um UpdateEntry
    private PendingDecision Decide(UpdateEntry entry, Manifest m, FileRecord? record, CancellationToken ct)
    {
        // 1) Já baixado E íntegro
        if (record?.Status == FileStatus.Completed)
        {
            var localHash = ComputeLocalHash(record.FileName);
            if (HashUtils.CompareSha256(localHash, entry.Integrity))
            {
                return new PendingDecision { Kind = Kind.SkipVerified, Entry = entry };
            }
            // hash local diverge do esperado — tratar como falha (rebaixar)
            _log.LogWarning("Hash de {0} divergente; rebaixando para rebaixar.", entry.FileName);
            return new PendingDecision { Kind = Kind.Failed, Entry = entry, NeedsRedownload = true };
        }

        // 2) Já baixado integralmente (registro sem status Completo mas bytes = size — hipótese pouco confiável; preferimos status explícito). Deixo.
        // 3) Falta totalmente
        if (record == null || record.Status == FileStatus.Pending || record.Status == FileStatus.Failed || record.UpdatedAt == default)
        {
            _log.LogInformation("Baixando {0} pela primeira vez.", entry.FileName);
            return new PendingDecision { Kind = Kind.DownloadFresh, Entry = entry };
        }

        // 4) Existe progresso parcial → retomar
        var known = record.GetCurrentOffset();
        if (known < record.SizeBytes) // needs care: record.SizeBytes from earlier download
        {
            _log.LogInformation("Retomando {0} de {1} bytes (faltam {2}).", entry.FileName, record.SizeBytes, record.SizeBytes - known);
            return new PendingDecision { Kind = Kind.Resume, Entry = entry, KnownOffset = known };
        }

        // chegou aqui: arquivo existe mas nenhum progresso registrado (corrompido/criação incompleta sem save) → baixar novamente do zero
        _log.LogWarning("Estado inconsistente de {0}; baixando novamente do zero.", entry.FileName);
        return new PendingDecision { Kind = Kind.DownloadFresh, Entry = entry };
    }

