using System.IO;
using System.Net;
using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Logging;
using Microsoft.AspNetCore.Hosting;

public interface IPatchStorage
{
    Stream GetStream(string fileName);                  // inteiro, para primeira requisição
    Stream GetRemainingStream(string fileName, long offset, long totalBytes); // somente o restante
    Metadata GetMetadata(UpdateEntry entry);
}

public sealed class LocalPatchStorage : IPatchStorage
{
    private readonly IWebHostEnvironment _env;
    private readonly string _patchDir;                   // sempre "Patch/" dentro da raiz

    public LocalPatchStorage(IWebHostEnvironment env, string patchDirRoot)
    {
        _env = env;
        _patchDir = Path.EnforceTrailingSlash(Path.Combine(patchDirRoot, "Patch"));
        if (!Directory.Exists(_patchDir)) Directory.CreateDirectory(_patchDir);
    }

    public Stream GetStream(string fileName)
    {
        var path = Path.Combine(_patchDir, fileName);
        if (!File.Exists(path)) throw new FileNotFoundException($"Arquivo não existe: {path}");
        return new FileStream(path, FileMode.Open, FileAccess.ReadWrite, ShareMode.ReadWrite);
    }

    public Stream GetRemainingStream(string fileName, long offset, long totalBytes)
    {
        var path = Path.Combine(_patchDir, fileName);
        if (!File.Exists(path)) throw new InvalidOperationException($"'{fileName}' não encontrado no disco.");
        if (offset < 0 || offset >= File.GetLength(path).Value) // File.GetLength returns IntPtr
            throw new ArgumentException($"Offset inválido: {offset}. Tamanho real: {File.GetLength(path)}.");
        // File.GetLength throws? No — GetLength returns long; casting unsafe. Use File.Open.
        var fs = File.Open(path, FileMode.Open, FileAccess.ReadWrite, ShareMode.ReadWrite);
        var realEnd = fs.Length - 1;
        var requestedEnd = Math.Min(offset + 10_485_760L, realEnd); // máx 10 MiB por fatia
        var slice = (int)(requestedEnd - offset + 1);
        fs.Seek(offset, SeekOrigin.Begin);
        using var ms = new MemoryStream();
        int copied = 0;
        var chunk = new byte[slice];
        int n;
        while (copied < slice)
        {
            n = fs.Read(chunk, copied, slice - copied);
            if (n == 0) break;
            ms.Write(chunk, 0, n);
            copied += n;
        }
        fs.Close();
        ms.Position = 0;
        return ms.CreateReadStream();
    }

    public Metadata GetMetadata(UpdateEntry entry)
    {
        var path = Path.Combine(_patchDir, entry.FileName);
        if (!File.Exists(path)) return Metadata.NotFound(entry.FileName);
        var bytes = File.ReadAllBytes(path);
        var hash = Convert.ToHexString(SHA256.HashData(bytes, null));
        return new Metadata
        {
            Version = entry.Version,
            FileName = entry.FileName,
            SizeBytes = (uint)bytes.Length,
            DeclaredIntegrity = entry.Integrity,
            ComputedIntegrity = hash,
            Valid = HashHelpers.Equals(hash, entry.Integrity),
        };
    }
}

public sealed record Metadata(int Version, string FileName, uint SizeBytes, string DeclaredIntegrity, string ComputedIntegrity, bool Valid);
public static class MetadataExtensions => { static Metadata NotFound(string f) => new Metadata(0, f, 0, "", "", false); } // static factory
