            _log.LogWarning("{0}: existe no disco mas hash DIVERGIU — rebaixando do zero.", entry.FileName);
            return new DecisionResult(DecisionKind.Fail, entry, null, "Hash divergente no arquivo local; será rebaixado.");
        }

        // sem registro / pendente / falha anterior → baixa do zero
        if (record == null || record.Status == FileStatus.Pending || record.Status == FileStatus.Failed || record.UpdatedAt == default)
        {
