    [HttpGet("file/{version}/{fileName}")]
    [AcceptRanges("bytes")]
    public async Task<IActionResult> StreamFile(
        int version, string fileName, [FromQuery] long offset = 0)
    {
        if (!Request.Headers.AcceptRanges.Contains("bytes") && offset > 0)
            return StatusCodes.Status426RequirementUnmet();

        try
        {
            var stream = _storage.OpenStream(fileName, offset);
            var realEnd = stream.Length - 1;
            var endSlice = Math.Min(offset + 10_485_760L, realEnd); // máxima 10 MiB por faixa
            var sliceLen = (int)(endSlice - offset + 1);

            using var body = new MemoryStream();
            int written = 0;
            var buf = new byte[sliceLen];
            int n;
            while (written < sliceLen)
            {
                n = await stream.ReadAsync(buf, written, sliceLen - written, CancellationToken.None);
                if (n == 0) break; // fim antes do solicitado (arquivo truncado)
                body.Write(buf, 0, n);
                written += n;
            }
            stream.Dispose();

            var contentLength = written;
            // se faltaram bytes (EOF), continua com o que veio
            var content = body.CreateReadStream();

            return Ok(content, "application/octet-stream")
                .WithHeaders(new HeaderValues
                {
                    ["Content-Range"]    = $"{offset}-{endSlice}/{_storage.RealLength(fileName)}",
                    ["Content-Length"]    = contentLength.ToString(),
                    ["Accept-Ranges"]     = "bytes",
                    ["Cache-Control"]     = "no-cache, no-transform, must-revalidate",
                    ["X-Accel-Buffering"] = "no",
                });
        }
        catch (FileNotFoundException ex)
        {
            _log.LogWarning("Arquivo não encontrado: {0} ({1})", fileName, ex.Message);
            return NotFound(); // o cliente interpreta como ausência do arquivo (404)
        }
    }
