```csharp
private void Dispatch(PendingDecision pd)
{
    switch (pd.Kind)
    {
        case DecisionKind.SkipMissing:
            var sec = pd.SegundosRestantes;
            if (sec > 0)
            {
                State.StatusLine = $"Salto em'{pd.Entry.FileName}' — restam {sec}s...";
                BeginSkipCountdown(sec);
            }
            else
            {
                State.History.Add(new SkippedItem(pd.Entry, "Arquivo ausente no servidor — pulado definitivamente.", 0));
                State.StatusLine = $"Pulou {pd.Entry.FileName} (não encontrado).";
            }
            break;

        case DecisionKind.SkipVerified:
            State.History.Add(new SkippedItem(pd.Entry, "Hash conferido — arquivo íntegro no disco.", 0));
            State.StatusLine += " • " + pd.Entry.FileName; // append? keep separate: set StatusDetail
            break;

        case DecisionKind.DownloadFresh:
            ActivateDownload(pd.Entry, 0, $"Primeira vez: baixando {pd.Entry.FileName}...");
            break;

        case DecisionKind.Resume:
            ActivateDownload(pd.Entry, (long)pd.KnownOffset!, $"Retomando {pd.Entry.FileName}: {PadragemKilobytes(pd.KnownOffset!)} de {PadraoMegabytes(...)} bytes salvos anteriormente — reiniciando de onde parou...");
            break;

        case DecisionKind.Fail:
            State.History.Add(new SkippedItem(pd.Entry, "Falha no download; será rebaixado em nova tentativa.", 0));
            State.ErrorText = $"Falha com {pd.Entry.FileName}: {pd.Mensagem ?? "erro desconhecido"}";
            State.Status = DownloadStatus.Error;
            State.StatusLine = $"Falha: {pd.Mensagem ?? "motivo não informado"}";
            _orch.TryReconnect();
            break;
    }
    // re-render: mudanças em State já bastam
}
