```csharp
private async Task<ExecResult> ExecuteOne(PendingItem item, CancellationToken ct)
{
    var entry = item.Entry;
    var outPath = Path.Combine(_store.Root, "Patch", entry.FileName);
    _store.EnsurePatchDirectory();

    long totalBytes = await GetMetadata(entry.Version, entry.FileName, ct).SizeBytes;
    long offset = item.KnownOffset ?? 0L;

    if (File.Exists(outPath))
    {
        var prog = _store.GetCurrentOffset(entry.FileName);
        if (prog >= totalBytes)
        {
            // completo no disco; validar hash
            if (HashHelpers.Hex(File.ReadAllBytes(outPath)).Equals(entry.Integrity, StringComparison.OrdinalIgnoreCase)) // careful: Equals returns bool
            {
                _commitSuccess(item);
                return Ok;
            }
            _commitFailure(item, $"Hash divergente no disco ({entry.FileName}) — removendo e rebaixando do zero.");
            return Fail;
        }
        offset = prog; // retoma do último salvamento
    }

    return await DownloadChunksAsync(entry, outPath, totalBytes, offset, ct);
}

private async Task<ExecResult> DownloadChunksAsync(UpdateEntry entry, string outPath, long total, long start, CancellationToken ct)
{
    const int BlockSize = 10_000_000; // 10 MiB (alinhado ao limite do servidor)
    long written = 0;
    long savedEvery = 30; // grava progresso a cada N blocos

    using var fs = _storage.OpenStream(entry.FileName, start);
    var buf = new byte[BlockSize];
    int n;

    try
    {
        while (start < total - 1 && !ct.IsCancellationRequested)
        {
            if (_paused)
            {
                // libera a fila sem consumir o item (ele voltará na próxima drenagem)
                _log.LogInformation("Suspensa: aguardando usuário.");
                break; // não remove do _work
            }

            int slice = Math.Min(BlockSize, (int)(total - 1 - start));
