        }
    }
    catch (OperationCanceledException)
    {
        // pausa/explicit cancel → não falhar, apenas informa
        return Interrupted;
    }
    catch (Exception ex)
    {
        _log.LogError(ex, "Erro grave no download de {0}", entry.FileName);
        _commitFailure(_, ex.Message);
        return Fail;
    }

    var endHash = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(outPath), null));
    if (!HashHelpers.Equals(endHash, entry.Integrity))
    {
        _commitFailure(_, $"Download concluído, mas hash não confere com o esperado — removendo e rebaixando {entry.FileName}.");
        return Fail;
    }
    _commitSuccess(item);
    return Ok;
