And in `GetMetadata`, `File.ReadAllBytes(path)` — for 1GB file metadata copy = 1GB RAM momentarily on server! Bad for big files. Optimize: read in segments up to, say, 10MB to compute SHA-256 incrementally (SHA256Context):

```csharp
public Metadata GetMetadata(UpdateEntry entry)
{
    var path = Path.Combine(_patchRoot, entry.FileName);
    if (!File.Exists(path)) return MetadataNotFound(entry.FileName);
    using var sha = new SHA256Managed();
    var hs = new MemoryStream();
    using var fs = new FileStream(path, FileMode.Open, FileAccess.Read, share: ShareMode.ReadWrite);
    int chunk = 4_000_000;
    byte[] b = new byte[chunk];
    long pos = 0;
    while (pos < File.GetLength(path))
    {
        int nr = fs.Read(b, 0, chunk);
        if (nr == 0) break;
        sha.Update(b, 0, nr);
        hs.Write(b, 0, nr);
        pos += nr;
    }
    fs.Dispose();
    var hex = Convert.ToHexString(sha.Hash);
    return new Metadata(entry.Version, entry.FileName, (uint)File.GetLength(path),
        entry.Integrity, hex, HashHelpers.Equals(hex, entry.Integrity));
}
```

