    var entry = item.Entry;
    var outPath = Path.Combine(_store.Root, "Patch", entry.FileName);
    _store.EnsurePatchDirectory();

    var meta = await FetchMetadata(entry.Version, entry.FileName, ct);
    if (meta is null)
    {
        _commitFailure(item.FileName, "Arquivo não encontrado no servidor (404 equivalente); rebaixando do zero.");
        return Fail;
    }

    long totalBytes = meta.SizeBytes;
    long start = item.KnownOffset ?? 0L;

    // revalidação de estado no disco
    if (File.Exists(outPath))
    {
        var prog = _store.GetCurrentOffset(entry.FileName);
        if (prog >= totalBytes)
        {
            if (HashHelpers.Hex(File.ReadAllBytes(outPath)).Equals(entry.Integrity, StringComparison.OrdinalIgnoreCase))
            {
                _commitOk(item, meta.ComputedIntegrity);
                return Ok;
            }
            _commitFailure(item.FileName, $"Hash divergente no disco — removendo {entry.FileName} e rebaixando do zero.");
            return Fail;
        }
        start = prog; // retoma
    }

    return await DownloadAndVerifyAsync(entry, outPath, totalBytes, start, ct);
}

private async Task<ExecResult> DownloadAndVerifyAsync(UpdateEntry entry, string outPath, long total, long start, CancellationToken ct)
{
    const int BlockSize = 10_000_000;
    long written = 0;

    using var fs = _storage.OpenStream(entry.FileName, start);
    var buf = new byte[BlockSize];
    int slice;
    try
    {
        while (start < total - 1 && !ct.IsCancellationRequested)
        {
            if (_paused)
            {
                _log.LogInformation("Operação suspensa pelo usuário — aguardando...");
                break; // mantém o item na fila
            }

            slice = Math.Min(BlockSize, (int)(total - 1 - start));
            if (slice <= 0) break;

            int n = await fs.ReadAsync(buf, 0, slice, Request.Context.CancellationToken);
            if (n == 0 && start > 0)
            {
                _commitFailure(entry.FileName, $"Servidor parou de responder no byte {start} — interrupção detectada.");
                return Fail;
            }
            var chunk = new byte[n];
            Array.Copy(buf, 0, chunk, 0, n);
            File.WriteAllBytes(outPath, chunk);
            written += n;
            if (written % 10_000_000 == 0)
            {
                _store.SaveCurrentOffset(entry.FileName, written);
                _cb.InvokeProgress(new ActiveDownload(
                    entry.FileName, entry.Version, written, total, DateTimeOffset.UtcNow,
                    note: written == 0 ? "Baixando..." : null));
            }
            await Task.Delay(TimeSpan.FromMilliseconds(20), ct);
        }
    }
    catch (OperationCanceledException)
    {
        // pausa solicitada/explicito — informar como interrupção leve e NÃO falhar
        return Interrupted;
    }
    catch (Exception ex)
    {
        _log.LogError(ex, "Erro grave no download de {0}", entry.FileName);
        _commitFailure(entry.FileName, $"Erro durante o download: {ex.Message}. Será rebaixado e rebaixado do zero na próxima tentativa.");
        return Fail;
    }

    // verificação final de hash
    var finalHash = Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(outPath), null));
    if (!HashHelpers.Equals(finalHash, entry.Integrity))
    {
        _commitFailure(entry.FileName, "Hash final não confere com o esperado — removendo o arquivo e rebaixando do zero.");
        return Fail;
    }

    _commitOk(item, entry.Integrity);
    return Ok;
}
